package local.cleartv.mobile;
import java.io.*;import java.net.*;import java.nio.*;import java.util.*;import java.util.concurrent.atomic.*;import java.security.*;import java.security.spec.*;import javax.crypto.Cipher;
public class AdbInstallCheck {
 static class Frame{int cmd,a,b;byte[] data;}
 static Frame read(InputStream in)throws Exception{ByteBuffer h=ByteBuffer.wrap(SdbClient.exact(in,24)).order(ByteOrder.LITTLE_ENDIAN);Frame f=new Frame();f.cmd=h.getInt();f.a=h.getInt();f.b=h.getInt();f.data=SdbClient.exact(in,h.getInt());return f;}
 static void send(OutputStream out,String cmd,int a,int b,byte[] data)throws Exception{int sum=0;for(byte v:data)sum+=v&255;out.write(ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN).putInt(SdbClient.code(cmd)).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(~SdbClient.code(cmd)).array());out.write(data);out.flush();}
 static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
  AdbIdentity identity=new AdbIdentity(null),restored=new AdbIdentity(identity.encoded());check(Arrays.equals(identity.publicKey(),restored.publicKey()),"Key identity not stable");
  byte[] token=new byte[20],file=new byte[70000];new Random(17).nextBytes(token);new Random(19).nextBytes(file);
  for(boolean reject:new boolean[]{false,true})try(ServerSocket server=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){AtomicReference<Throwable> failure=new AtomicReference<>();Thread fake=new Thread(()->{try(Socket peer=server.accept()){peer.setSoTimeout(5000);InputStream in=peer.getInputStream();OutputStream out=peer.getOutputStream();check(read(in).cmd==SdbClient.code("CNXN"),"No CNXN");send(out,"AUTH",1,0,token);Frame sig=read(in);check(sig.cmd==SdbClient.code("AUTH")&&sig.a==2,"No signature");Cipher rsa=Cipher.getInstance("RSA/ECB/PKCS1Padding");rsa.init(Cipher.DECRYPT_MODE,KeyFactory.getInstance("RSA").generatePublic(new RSAPublicKeySpec(identity.key.getModulus(),identity.key.getPublicExponent())));byte[] digest=rsa.doFinal(sig.data);check(digest.length==35&&Arrays.equals(token,Arrays.copyOfRange(digest,15,35)),"Token was rehashed or signature invalid");send(out,"AUTH",1,0,token);Frame pub=read(in);check(pub.a==3&&pub.data[pub.data.length-1]==0,"Public key missing terminator");byte[] key=Base64.getDecoder().decode(new String(pub.data,"UTF-8").split(" ")[0]);check(key.length==524,"Wrong ADB key layout");check(ByteBuffer.wrap(key).order(ByteOrder.LITTLE_ENDIAN).getInt()==64,"Wrong modulus word count");send(out,"CNXN",0x1000000,4096,"device::fixture\0".getBytes("UTF-8"));Frame open=read(in);check(new String(open.data,"UTF-8").equals("sync:\0"),"Wrong SYNC service");int id=open.a;send(out,"OKAY",7,id,new byte[0]);ByteArrayOutputStream buffered=new ByteArrayOutputStream(),received=new ByteArrayOutputStream();boolean done=false;
   while(!done){Frame f=read(in);check(f.cmd==SdbClient.code("WRTE"),"Expected SYNC data");buffered.write(f.data);send(out,"OKAY",7,id,new byte[0]);byte[] data=buffered.toByteArray();int offset=0;while(data.length-offset>=8){String cmd=new String(data,offset,4,"US-ASCII");int n=ByteBuffer.wrap(data,offset+4,4).order(ByteOrder.LITTLE_ENDIAN).getInt();if(cmd.equals("DONE")){check(data.length-offset==8,"DONE must be timestamp header, not length plus payload");done=true;offset+=8;break;}if(data.length-offset<8+n)break;byte[] body=Arrays.copyOfRange(data,offset+8,offset+8+n);if(cmd.equals("SEND"))check(new String(body,"UTF-8").equals("/data/local/tmp/test.apk,33188"),"Missing Android file mode");else if(cmd.equals("DATA"))received.write(body);else throw new AssertionError("Unknown SYNC command");offset+=8+n;}buffered.reset();buffered.write(data,offset,data.length-offset);}
   check(Arrays.equals(file,received.toByteArray()),"APK bytes changed");byte[] result=reject?"FAIL\u0006\0\0\0denied".getBytes("US-ASCII"):new byte[]{'O','K','A','Y',0,0,0,0};send(out,"WRTE",7,id,result);check(read(in).cmd==SdbClient.code("OKAY"),"No SYNC ACK");check(read(in).cmd==SdbClient.code("CLSE"),"No SYNC close");if(!reject){Frame shell=read(in);check(new String(shell.data,"UTF-8").equals("shell:pm install -r --user 0 /data/local/tmp/test.apk\0"),"Install command changed");send(out,"OKAY",8,shell.a,new byte[0]);send(out,"WRTE",8,shell.a,"Success\n".getBytes("UTF-8"));check(read(in).cmd==SdbClient.code("OKAY"),"No shell ACK");send(out,"CLSE",8,shell.a,new byte[0]);check(read(in).cmd==SdbClient.code("CLSE"),"No shell close");}
  }catch(Throwable e){failure.set(e);}});fake.start();try(SdbClient client=new SdbClient("127.0.0.1",server.getLocalPort(),restored)){try{client.push(file,"/data/local/tmp/test.apk",null);check(!reject,"Ignored failed transfer");check(client.shell("pm install -r --user 0 /data/local/tmp/test.apk").equals("Success"),"Install success not returned");}catch(IOException e){if(!reject)throw e;check(e.getMessage().contains("FAIL"),"Wrong failure");}}fake.join(6000);check(!fake.isAlive(),"Transport hung");if(failure.get()!=null)throw new AssertionError("Fake ADB peer failed",failure.get());}
  System.out.println("PASS: ADB RSA signature/key persistence, approval handshake, 70KB SYNC transfer, Android DONE framing, install response and transfer rejection. No physical Fire TV tested.");
 }
}
